package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;

public class B8cRenameSheetManifestTest extends TestCase {
    private ObjectNode snapshot(){return (ObjectNode)parse("{\"id\":\"p\",\"name\":\"P\",\"sheetOrder\":[\"s\",\"other\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Source\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"a\",\"t\":1}}}},\"other\":{\"id\":\"other\",\"name\":\"Other\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{}}},\"activeSheet\":\"s\"}");}
    private ArrayNode scopes(){return (ArrayNode)parse("[{\"sheetId\":\"s\",\"range\":\"A1:F6\"}]");}
    private ObjectNode action(){ObjectNode a=obj().put("schemaVersion","2.0").put("type","renameSheet").put("newSheetName","Renamed");a.set("target",obj().put("sheetId","s"));return a;}
    private void reject(Runnable r){try{r.run();fail("unsafe rename accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testRenamePreservesIdsContentAndOrder(){ObjectNode before=snapshot(),m=StructureManifest.preview(before,action(),scopes()),saved=StructureManifest.apply(before,m);assertEquals("Renamed",saved.path("sheets").path("s").path("name").asText());assertEquals("Other",saved.path("sheets").path("other").path("name").asText());assertEquals("a",saved.path("sheets").path("s").path("cellData").path("0").path("0").path("v").asText());assertEquals(before.path("sheetOrder"),saved.path("sheetOrder"));assertEquals("s",saved.path("activeSheet").asText());assertEquals("Renamed",m.path("structureReadback").path("newSheetName").asText());StructureManifest.validateReceipt(m,m.path("structureReadback"));ObjectNode change=obj().put("kind","controlled-structure").put("operationId","call").put("afterHash",hash(saved));change.set("structurePatch",m.path("structurePatch"));ObjectNode write=obj().put("transportVersion",2).put("callId","call").put("persistenceStatus","SAVED").put("validation","PASSED").put("loadedRevision",hash(saved)).put("sourceRevision",hash(saved));write.set("executedChange",change);ObjectNode verify=obj().put("kind","matches_structure").put("sheetId","s").put("range","A1:F6");verify.set("write",write);assertTrue(AgentTools.verify(saved,verify).path("passed").asBoolean());}
    public void testScopeCollisionDependenciesAndGate(){ObjectNode a=action();reject(()->StructureManifest.preview(snapshot(),a,(ArrayNode)parse("[{\"sheetId\":\"s\",\"range\":\"A1:E6\"}]")));ObjectNode duplicate=a.deepCopy();duplicate.put("newSheetName","other");reject(()->StructureManifest.preview(snapshot(),duplicate,scopes()));ObjectNode unchanged=a.deepCopy();unchanged.put("newSheetName","Source");reject(()->StructureManifest.preview(snapshot(),unchanged,scopes()));ObjectNode formula=snapshot();((ObjectNode)formula.path("sheets").path("s").path("cellData").path("0").path("0")).put("f","=1+1");reject(()->StructureManifest.preview(formula,a,scopes()));ObjectNode m=StructureManifest.preview(snapshot(),a,scopes()),forged=m.deepCopy();((ObjectNode)forged.path("structurePatch")).put("newSheetName","Forged");reject(()->StructureManifest.apply(snapshot(),forged));ArrayNode actions=arr().add(a);reject(()->WriteManifest.classify(actions,false,false,false,false,false,true));assertEquals("controlled-values",WriteManifest.classify(actions,false,false,false,false,false,false,true));assertFalse(WriteManifest.availableActions(false,false,false,false,false,true).contains("renameSheet"));}
}
